          "existing_id": "it_followup_all_or_nothing"
        }
      ],
      "relation_refs": []
    },
    "additional_contents": [],
    "response_targets": [
      {
        "owner_content": "rfl_cycle_insight",
        "subject": {
          "content_handle": "rfl_cycle_insight"
        },
        "interaction": "evaluation"
      }
    ],
    "decision_intent": "reflection"
  },
  "reply_segments": [
    {
      "text": "Понимаю — звучит как устойчивый цикл: усталость на работе ведёт к пропуску обеда и вечеру переедание, а мысль «всё испортил» завершает день и ставит на паузу попытки на недели. Может ли такая формулировка быть полезной для вас — поддерживаете ли вы её, частично поддерживаете или видите что-то неверным или пропущенным?",
